#!/usr/bin/env bash
# LogVault setup: arranges the project and pushes it once. Run from the repo folder.
set -euo pipefail

say()  { printf '\n\033[1;34m==>\033[0m %s\n' "$*"; }
fail() { printf '\n\033[1;31mSTOP:\033[0m %s\n' "$*" >&2; exit 1; }

SELF="$(realpath "$0")"
SELFNAME="$(basename "$SELF")"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

REPO="$(git rev-parse --show-toplevel 2>/dev/null)" || fail "Open your repo folder in the terminal first (cd /workspaces/Logvault-)."
cd "$REPO"
git remote get-url origin >/dev/null 2>&1 || fail "This repo has no 'origin' remote."
say "Getting the latest from GitHub"
git pull -q --ff-only origin "$(git symbolic-ref --short HEAD)" 2>/dev/null || true

ZIPNAME="project.zip"
if grep -q '^__ZIP_BASE64__$' "$SELF"; then
  say "Reading the project from $SELFNAME"
  sed -n '/^__ZIP_BASE64__$/,$p' "$SELF" | tail -n +2 | base64 -d > "$TMP/$ZIPNAME"
  ZIP="$TMP/$ZIPNAME"
else
  ZIP="$(find "$REPO" "$HOME" /workspaces -maxdepth 2 -iname '*logvault*.zip' 2>/dev/null | head -n 1 || true)"
  [ -n "$ZIP" ] && [ -f "$ZIP" ] || fail "The project is not in this file. Upload the LogVault zip to the repo and run again."
  ZIPNAME="$(basename "$ZIP")"
fi

mkdir -p "$TMP/x"
unzip -q "$ZIP" -d "$TMP/x" 2>/dev/null || python3 -c 'import sys,zipfile; zipfile.ZipFile(sys.argv[1]).extractall(sys.argv[2])' "$ZIP" "$TMP/x"
SERVER="$(find "$TMP/x" -name server.js -not -path '*/__MACOSX/*' | head -n 1 || true)"
[ -n "$SERVER" ] || fail "server.js was not found inside the project."
SRC="$(dirname "$SERVER")"
cat > "$TMP/layout.txt" <<'LAYOUT'
. README.md
. package.json
. package-lock.json
. .npmrc
. .gitignore
. server.js
. site.config.js
public admin.html
public manifest.json
public robots.txt
public favicon.png
public favicon-32.png
public apple-touch-icon.png
public welcome-popup.js
public theme.css
public script.js
public/img vault-icon-192.png
public/img vault-icon-512.png
public/img vault-maskable-512.png
public/vault home.html
public/vault login.html
public/vault register.html
public/vault dashboard.html
public/vault products.html
public/vault sms.html
public/vault deposit.html
public/vault fund-crypto.html
public/vault transactions.html
public/vault orders.html
public/vault profile.html
public/vault api-access.html
public/vault admin-logs.html
public/vault vault.js
public/vault vault.css
public/vault vault-logo.png
public/css admin-customer-theme.css
public/css admin-pro.css
public/css layout-polish.css
public/css lvt-ui-fixes.css
public/css marketplace-standard.css
public/css mobile-fix.css
public/css redesign.css
public/css responsive-device-fit.css
public/css style.css
public/css vault-brand.css
public/css vault-final.css
public/css vault-glass-ui.css
public/css vault-mobile-polish.css
public/css vault-theme.css
public/css vault-ui.css
public/js announcements.js
public/js app-guide.js
public/js app-shell.js
public/js auth-keeper.js
public/js back-button.js
public/js country-select.js
public/js extras-customer.js
public/js global-pay.js
public/js i18n.js
public/js live-support.js
public/js lvt-menu-guard.js
public/js lvt-ui.js
public/js money.js
public/js ops-admin.js
public/js vault-brand.js
public/js vault-select-sheet.js
public/js vault-ui.js
public/js wallet.js
lib benotp.js
lib brand-logos.js
lib campaigns.js
lib countries.js
lib countries.data.json
lib engagement.js
lib extras.js
lib flw-methods.js
lib fx.js
lib geo.js
lib global-payments.js
lib korapay.js
lib minipdf.js
lib mailer.js
lib market2.js
lib mysql.js
lib opaque-ref.js
lib ops.js
lib platform.js
lib settings.js
lib vault-logs.js
lib vault-upgrade.js
lib welcomepopup.js
LAYOUT
LAYOUT="$(awk 'NF==2' "$TMP/layout.txt")"
EXPECTED="$(awk '{print $2}' <<< "$LAYOUT" | sort)"
IN_ZIP="$(cd "$SRC" && find . -maxdepth 1 -type f -printf '%f\n' | sort)"
MISSING="$(comm -23 <(printf '%s\n' "$EXPECTED") <(printf '%s\n' "$IN_ZIP") || true)"
[ -z "$MISSING" ] || fail "Missing from the project: $(echo $MISSING)"

if command -v node >/dev/null 2>&1; then
  say "Checking server code for syntax errors"
  while read -r dir name; do
    if [ "$name" = "server.js" ] || [ "$dir" = "lib" ]; then
      case "$name" in *.js) node --check "$SRC/$name" || fail "Syntax error in $name. Nothing was changed." ;; esac
    fi
  done <<< "$LAYOUT"
fi

OLD="$(find . -mindepth 1 -maxdepth 1 ! -name .git ! -name "$SELFNAME" ! -name "$ZIPNAME" -printf '%f\n' | sort)"
if [ -n "$OLD" ]; then
  say "These items in the repo will be replaced by the arranged project:"
  echo "$OLD" | sed 's/^/   /'
  read -r -p "Type yes to replace them: " ans
  [ "$ans" = "yes" ] || fail "Stopped. Nothing was changed."
  find . -mindepth 1 -maxdepth 1 ! -name .git ! -name "$SELFNAME" ! -name "$ZIPNAME" -exec rm -rf {} +
fi

say "Arranging $(wc -l <<< "$LAYOUT") files into the project folders"
while read -r dir name; do
  dest="$name"
  [ "$dir" = "." ] || dest="$dir/$name"
  mkdir -p "$REPO/$(dirname "$dest")"
  cp "$SRC/$name" "$REPO/$dest"
done <<< "$LAYOUT"

git rm -r -q --cached --ignore-unmatch -- "$SELFNAME" "$ZIPNAME" 2>/dev/null || true
git add -A -- . ":(exclude)$SELFNAME" ":(exclude)$ZIPNAME"
if git diff --cached --quiet; then
  say "Nothing changed. The repo already matches the project."
  exit 0
fi

ID=()
git config user.email >/dev/null 2>&1 || ID=(-c user.name="LogVault setup" -c user.email="setup@logvault.local")
say "Committing"
git ${ID[@]+"${ID[@]}"} commit -q -m "Arrange LogVault project into deployable layout

Co-Authored-By: Claude Haiku 5.5 <noreply@anthropic.com>
Claude-Session: https://claude.ai/code/session_01SbmQGgomXvedPTvwrNKUaZ"

BRANCH="$(git symbolic-ref --short HEAD)"
say "Pushing to origin/$BRANCH"
git push -u origin "$BRANCH" \
  || fail "Push was refused. Run: git pull --rebase origin $BRANCH   then run this script again."
say "Done. The arranged project is pushed to GitHub. Now connect the repo in Render and deploy."
exit 0
